using System.Collections;
using Astrea.BattleActions;
using LittleLeo;
using UnityEngine;

namespace Astrea;

public class CompanionAbility : UnitsDiceActivation
{
	[Header("VFX")]
	[SerializeField]
	private GameObject sentinelUsingDiceVFX;

	private CompanionInitializer companionInitializer;

	private bool playActivationAnimationEnqueued;

	public bool PlayActivationAnimationEnqueued => playActivationAnimationEnqueued;

	private void Awake()
	{
		companionInitializer = GetComponent<CompanionInitializer>();
	}

	public void RestoreDiceToDefaultState()
	{
		if (BasicDiceSpawned)
		{
			ResetDice(ref basicDice, basicDiceInstance);
			if (boosted && BoostDiceSpawned)
			{
				ResetDice(ref boostDice, boostDiceInstance);
			}
		}
	}

	public override void Spawn3DDice()
	{
		SetReplicateDiceFaces(ref basicDice);
		if (boosted)
		{
			SetReplicateDiceFaces(ref boostDice);
		}
		UpdateActionValueModifier();
		base.Spawn3DDice();
		static void SetReplicateDiceFaces(ref Dice die)
		{
			int num = -1;
			for (int i = 0; i < die.GetDiceFaces().Length; i++)
			{
				DiceFace diceFace = die.GetDiceFaces()[i];
				if (diceFace.BattleAction is ChaoticAction && !(diceFace.BattleAction is InvokeAction))
				{
					num = i;
					break;
				}
			}
			if (num > -1)
			{
				ChaoticAction obj = die.GetDiceFaces()[num].BattleAction as ChaoticAction;
				DiceFace[] array = obj.GetRandomDice(die.GetDiceFaces()[num].ActionValue).CopyDiceFacesAsNewInstances();
				if (obj.RandomPlayerDieSentinelAction)
				{
					num = -1;
					for (int j = 0; j < array.Length; j++)
					{
						DiceFace diceFace2 = array[j];
						if (diceFace2.BattleAction is ChaoticAction && !(diceFace2.BattleAction is InvokeAction))
						{
							num = j;
							break;
						}
					}
					if (num > -1)
					{
						array = (array[num].BattleAction as ChaoticAction).GetRandomDice(array[num].ActionValue).CopyDiceFacesAsNewInstances();
					}
				}
				for (int k = 0; k < array.Length; k++)
				{
					DiceFace diceFace3 = die.GetDiceFaces()[k];
					if (!(diceFace3.BattleAction is ChaoticAction))
					{
						array[k] = diceFace3;
					}
					else if (diceFace3.BattleAction is InvokeAction)
					{
						array[k] = diceFace3;
					}
				}
				die.SetDiceFaces(array);
			}
		}
	}

	public void PlayActivationAnimation()
	{
		playActivationAnimationEnqueued = true;
		ReferenceSingleton<SFXHandler>.Instance.PlaySFX(companionInitializer.CompanionSFXData.UsingDice);
		ReferenceSingleton<VFXHandler>.Instance.SpawnVFX(sentinelUsingDiceVFX, base.transform.position, 5f);
		StartCoroutine(ActivationAnimation(null));
		StartCoroutine(CompanionActivationAnimation());
	}

	private IEnumerator CompanionActivationAnimation()
	{
		yield return new WaitForSeconds(attackAnimationDuration + 0.1f);
		playActivationAnimationEnqueued = false;
	}

	public int GetSeaRequiemAmount(BattleAction seaRequiemAction)
	{
		int num = 0;
		if (BasicDiceSpawned)
		{
			if (basicDiceInstance.ActionEnabled && basicDice.DiceHasAction(seaRequiemAction))
			{
				num++;
			}
			if (boosted && BoostDiceSpawned && boostDiceInstance.ActionEnabled && boostDice.DiceHasAction(seaRequiemAction))
			{
				num++;
			}
		}
		return num;
	}
}
